        try {
            $dbForms = $this->db('mlite_rme_form')->select('route_form, target_aktor')->toArray();
            foreach ($dbForms as $dbf) {
                $rf = strtolower(str_replace(['form', '_form'], '', $dbf['route_form']));
                if (!empty($dbf['target_aktor'])) {
                    $staticMap[$rf] = $dbf['target_aktor'];
