public function getPatientContext($no_rawat)
    {
        if (empty($no_rawat)) {
            return [];
        }

        if (is_numeric($no_rawat) && strlen($no_rawat) < 6) {
            $no_rawat = str_pad($no_rawat, 6, '0', STR_PAD_LEFT);
        }

        $reg = $this->db('reg_periksa')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
            ->leftJoin('poliklinik', 'poliklinik.kd_poli = reg_periksa.kd_poli')
            ->leftJoin('dokter', 'dokter.kd_dokter = reg_periksa.kd_dokter')
            ->leftJoin('penjab', 'penjab.kd_pj = reg_periksa.kd_pj')
            ->where('reg_periksa.no_rawat', $no_rawat)
            ->orWhere('reg_periksa.no_rkm_medis', $no_rawat)
            ->desc('reg_periksa.tgl_registrasi')
            ->desc('reg_periksa.jam_reg')
            ->select('reg_periksa.*, pasien.nm_pasien, pasien.jk, pasien.tmp_lahir, pasien.tgl_lahir, pasien.umur, pasien.alamat, pasien.no_ktp, pasien.no_tlp, pasien.gol_darah, pasien.agama, pasien.pnd, pasien.pekerjaan, pasien.stts_nikah, pasien.suku_bangsa, pasien.bahasa_pasien, poliklinik.nm_poli, dokter.nm_dokter as dokter_reg, penjab.png_jawab')
            ->oneArray();

        if (!$reg) {
            return [];
        }

        $resolved_no_rawat = $reg['no_rawat'];

        // Info Rawat Inap
        $ranap = $this->db('kamar_inap')
            ->leftJoin('kamar', 'kamar.kd_kamar = kamar_inap.kd_kamar')
            ->leftJoin('bangsal', 'bangsal.kd_bangsal = kamar.kd_bangsal')
            ->where('kamar_inap.no_rawat', $resolved_no_rawat)
            ->desc('kamar_inap.tgl_masuk')
            ->desc('kamar_inap.jam_masuk')
            ->select('kamar_inap.kd_kamar, bangsal.nm_bangsal, kamar_inap.tgl_masuk, kamar_inap.jam_masuk, kamar_inap.tgl_keluar, kamar_inap.jam_keluar')
            ->oneArray();

        // DPJP Ranap
        $dpjp = $this->db('dpjp_ranap')
            ->leftJoin('dokter', 'dokter.kd_dokter = dpjp_ranap.kd_dokter')
            ->where('dpjp_ranap.no_rawat', $resolved_no_rawat)
            ->select('dokter.kd_dokter, dokter.nm_dokter')
            ->oneArray();

        // Diagnosa Utama
        $diag = $this->db('diagnosa_pasien')
            ->leftJoin('penyakit', 'penyakit.kd_penyakit = diagnosa_pasien.kd_penyakit')
            ->where('diagnosa_pasien.no_rawat', $resolved_no_rawat)
            ->asc('diagnosa_pasien.prioritas')
            ->select('penyakit.kd_penyakit, penyakit.nm_penyakit')
            ->oneArray();

        $ruangan = '';
        if ($ranap && !empty($ranap['nm_bangsal'])) {
            $ruangan = $ranap['nm_bangsal'] . (!empty($ranap['kd_kamar']) ? ' (' . $ranap['kd_kamar'] . ')' : '');
        } elseif (!empty($reg['nm_poli'])) {
            $ruangan = 'Poli ' . $reg['nm_poli'];
        }

        $dokter_nama = $dpjp['nm_dokter'] ?? ($reg['dokter_reg'] ?? '');
        $kd_dokter = $dpjp['kd_dokter'] ?? ($reg['kd_dokter'] ?? '');

        return [
            'no_rawat' => $resolved_no_rawat,
            'no_rkm_medis' => $reg['no_rkm_medis'],
            'nm_pasien' => $reg['nm_pasien'],
            'jk' => $reg['jk'],
            'jk_text' => ($reg['jk'] == 'L' ? 'Laki-Laki' : ($reg['jk'] == 'P' ? 'Perempuan' : '')),
            'tmp_lahir' => $reg['tmp_lahir'],
            'tgl_lahir' => $reg['tgl_lahir'],
            'umur' => $reg['umur'],
            'alamat' => $reg['alamat'],
            'no_ktp' => $reg['no_ktp'],
            'no_tlp' => $reg['no_tlp'],
            'gol_darah' => $reg['gol_darah'] ?? '',
            'agama' => $reg['agama'] ?? '',
            'agama_pasien' => $reg['agama'] ?? '',
            'pnd' => $reg['pnd'] ?? '',
            'pendidikan' => $reg['pnd'] ?? '',
            'pendidikan_terakhir' => $reg['pnd'] ?? '',
            'pekerjaan' => $reg['pekerjaan'] ?? '',
            'pekerjaan_pasien' => $reg['pekerjaan'] ?? '',
            'stts_nikah' => $reg['stts_nikah'] ?? '',
            'status_perkawinan' => $reg['stts_nikah'] ?? '',
            'status_pernikahan' => $reg['stts_nikah'] ?? '',
            'suku_bangsa' => $reg['suku_bangsa'] ?? '',
            'bahasa_pasien' => $reg['bahasa_pasien'] ?? '',
            'kd_poli' => $reg['kd_poli'],
            'nm_poli' => $reg['nm_poli'],
            'tgl_registrasi' => $reg['tgl_registrasi'] ?? '',
            'jam_reg' => $reg['jam_reg'] ?? '',
            'status_lanjut' => $reg['status_lanjut'] ?? 'Ralan',
            'stts' => $reg['stts'] ?? '',
            'status_bayar' => $reg['status_bayar'] ?? '',
            'stts_daftar' => $reg['stts_daftar'] ?? '',
            'kd_kamar' => $ranap['kd_kamar'] ?? '',
            'nm_bangsal' => $ranap['nm_bangsal'] ?? '',
            'ruangan' => $ruangan,
            'kd_dokter' => $kd_dokter,
            'dokter' => $dokter_nama,
            'nm_dokter' => $dokter_nama,
            'penanggung_jawab' => $reg['p_jawab'] ?? '',
            'hubungan_pj' => $reg['hubunganpj'] ?? '',
            'alamat_pj' => $reg['almt_pj'] ?? '',
            'diagnosa' => $diag ? ($diag['kd_penyakit'] . ' - ' . $diag['nm_penyakit']) : '',
            'png_jawab' => $reg['png_jawab'] ?? ''
        ];
    }

    // ============================================================
    // UNIVERSAL RME PATIENT INFO & LIVE CETAK ENGINE
    // ============================================================

    public function anyUniversalpatientinfo()
    {
        $no_rawat = $_GET['no_rawat'] ?? '';
        $patient = $this->getPatientContext($no_rawat);

        if (!empty($patient)) {
            $patient['success'] = true;
            $patient['nama_pasien'] = $patient['nm_pasien'];
            $patient['jenis_kelamin'] = $patient['jk'];
            $patient['tanggal_lahir'] = $patient['tgl_lahir'];
            $patient['tgl_lahir'] = $patient['tgl_lahir'];
        } else {
            $patient = ['success' => false];
        }

        if (ob_get_length()) {
            ob_clean();
        }
        header('Content-Type: application/json');
        echo json_encode($patient);
        exit();
    }

    public function anyTteverifysave()
    {
        if (ob_get_length()) {
            ob_clean();
        }
        header('Content-Type: application/json');

        try {
            $ref_type   = trim($_POST['ref_type'] ?? 'form_rme');
            $ref_id     = trim($_POST['ref_id'] ?? '');
            $passphrase = trim($_POST['passphrase'] ?? '');
            $signerName = trim($_POST['signer_name'] ?? '');
            $signerRole = trim($_POST['signer_role'] ?? '');

            if (empty($passphrase)) {
                throw new \Exception("Kata sandi (passphrase) verifikasi TTE wajib diisi.");
            }

            $userId = $_SESSION['mlite_user'] ?? null;
            if (!$userId) {
                throw new \Exception("Sesi login Anda telah berakhir, silakan login ulang.");
            }

            $user = $this->db('mlite_users')->where('id', $userId)->oneArray();
            if (!$user) {
                throw new \Exception("Pengguna tidak ditemukan.");
            }

            if (!password_verify($passphrase, $user['password'])) {
                throw new \Exception("Kata sandi (login) tidak valid!");
            }

            if (empty($signerName)) {
                $signerName = $user['fullname'] ?? ($user['username'] ?? 'Petugas RS');
            }
            if (empty($signerRole)) {
                $signerRole = $user['role'] ?? 'petugas';
            }

            $hash = hash('sha256', uniqid('tte_', true) . bin2hex(random_bytes(16)) . $ref_type . $ref_id . $userId);

            $dir = WEBAPPS_PATH . '/berkas/esignature/';
            if (!file_exists($dir)) {
                @mkdir($dir, 0755, true);
            }
            $filename = 'tte_' . time() . '_' . substr($hash, 0, 10) . '.png';
            $path = $dir . $filename;
            if (!file_exists($path)) {
                $img = imagecreatetruecolor(1, 1);
                imagesavealpha($img, true);
                $color = imagecolorallocatealpha($img, 0, 0, 0, 127);
                imagefill($img, 0, 0, $color);
                @imagepng($img, $path);
                @imagedestroy($img);
            }

            $signedAt = date('Y-m-d H:i:s');
            $this->db('mlite_esignatures')->save([
                'ref_type'       => $ref_type,
                'ref_id'         => $ref_id ?: (string)time(),
                'signer_role'    => $signerRole,
                'signer_id'      => $user['username'] ?? (string)$userId,
                'signer_name'    => $signerName,
                'signature_path' => $filename,
                'signature_hash' => $hash,
                'signed_at'      => $signedAt,
                'ip_address'     => $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1',
                'user_agent'     => $_SERVER['HTTP_USER_AGENT'] ?? 'MLITE-RME-Client',
                'legal_basis'    => 'UU ITE No 11 Tahun 2008 & Permenkes RME No 24 Tahun 2022',
                'audit_json'     => json_encode([
                    'user_id'    => $userId,
                    'username'   => $user['username'] ?? '',
                    'signed_at'  => $signedAt,
                    'ref_type'   => $ref_type,
                    'ref_id'     => $ref_id
                ])
            ]);

            $verifyUrl = url(['esignature', 'verify', $hash]);

            echo json_encode([
                'status'         => 'success',
                'hash'           => $hash,
                'signer_name'    => $signerName,
                'signer_role'    => $signerRole,
                'signed_at'      => $signedAt,
                'signed_at_indo' => date('d-m-Y H:i', strtotime($signedAt)) . ' WITA',
                'verify_url'     => $verifyUrl,
                'message'        => 'Tanda tangan elektronik (TTE) berhasil diverifikasi dan disimpan.'
            ]);
            exit();
        } catch (\Throwable $e) {
            http_response_code(400);
            echo json_encode([
                'status'  => 'error',
                'message' => $e->getMessage()
            ]);
            exit();
        }
    }

