    public function prepareCetakData(array $data = [], string $template = ''): array
    {
        @ini_set('display_errors', '0');

        $bulan = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        $tglToday = date('d') . ' ' . $bulan[(int)date('m')] . ' ' . date('Y');

        $tglDokumen = $data['tgl_dokumen'] ?? ($data['tanggal'] ?? ($data['tgl_registrasi'] ?? date('Y-m-d')));
        $tglParts = explode('-', substr((string)$tglDokumen, 0, 10));
        if (count($tglParts) == 3 && checkdate((int)$tglParts[1], (int)$tglParts[2], (int)$tglParts[0])) {
            $tglDokumenIndo = (int)$tglParts[2] . ' ' . $bulan[(int)$tglParts[1]] . ' ' . $tglParts[0];
        } else {
            $tglDokumenIndo = $tglToday;
        }

        $tglLahirIndo = '-';
        if (!empty($data['tgl_lahir']) && $data['tgl_lahir'] !== '0000-00-00') {
            $tglLahirParts = explode('-', substr((string)$data['tgl_lahir'], 0, 10));
            if (count($tglLahirParts) == 3 && checkdate((int)$tglLahirParts[1], (int)$tglLahirParts[2], (int)$tglLahirParts[0])) {
                $tglLahirIndo = (int)$tglLahirParts[2] . ' ' . $bulan[(int)$tglLahirParts[1]] . ' ' . $tglLahirParts[0];
            }
        }

        $rmRaw = ltrim((string)($data['no_rkm_medis'] ?? ''), "'");
        $rm = str_pad($rmRaw, 6, '0', STR_PAD_LEFT);
        $jk = $data['jk'] ?? ($data['jenis_kelamin'] ?? '-');
        $lp = ($jk === 'L') ? '(Laki-laki)' : (($jk === 'P') ? '(Perempuan)' : '-');

        $defaults = [
            'no_rkm_medis' => $rm,
            'no_rawat' => '-',
            'nm_pasien' => '-',
            'nama_pasien' => '-',
            'jk' => $jk,
            'jenis_kelamin' => $jk,
            'lp' => $lp,
            'jk_label' => ($jk === 'L') ? 'L' : (($jk === 'P') ? 'P' : '-'),
            'jk_pasien' => $jk,
            'jk_pihak' => $jk,
            'tgl_lahir' => '',
            'tanggal_lahir' => '',
            'tgl_lahir_indo' => $tglLahirIndo,
            'tanggal_lahir_indo' => $tglLahirIndo,
            'tgl_lahir_pasien_indo' => $tglLahirIndo,
            'tgl_dokumen_indo' => $tglDokumenIndo,
            'tanggal_indo' => $tglDokumenIndo,
            'tanggal_pelaksanaan_indo' => $tglDokumenIndo,
            'tgl_surat_indo' => $tglDokumenIndo,
            'umur' => '-',
            'umur_pasien' => '-',
            'alamat' => '-',
            'alamat_pasien' => '-',
            'ruangan' => '-',
            'nm_bangsal' => '-',
            'nm_poli' => '-',
            'dokter' => '-',
            'nm_dokter' => '-',
            'nama_dokter' => '-',
            'nip_dpjp' => '-',
            'kd_dokter' => '-',
            'diagnosa' => '-',
            'diagnosis_medis' => '-',
            'nama_pasien_pj' => '-',
            'nama_pemberi_edukasi' => '-',
            'jam_wita' => date('H:i'),
            'detail' => [],
            'detail_obat' => [],
            'rows' => [],
            'katRows' => [],
            'rendered_rows' => [],
            'pelaksanaan' => [],
            'pengkajian' => [
                'hambatan' => [],
                'keterbatasan' => [],
                'kebutuhan' => []
            ],
            'asesmen' => [],
            'dewasaColsLeft' => [],
            'dewasaColsRight' => [],
            'h2Cols' => [],
            'p1' => [],
            'p2' => [],
            'days' => [],
            'dokumen_list' => [],
            'rm_digits' => ['0','0','0','0','0','0'],
            'padded_diagnosa' => [],
            'padded_alergi' => [],
            'padded_ranap' => [],
            'padded_operasi' => [],
            'padded_obat' => [],
            'vital_rows' => [],
            'pajanan_rows' => [],
            'daftar_obat' => [],
            'daftar_alat' => [],
            'pemeriksaan_penunjang' => [],
            'admisi_detail' => [],
            'transfer_detail' => [],
            'pulang_detail' => [],
            'mst_penurunan_bb' => '0',
            'mst_asupan_makanan' => '0',
            'mst_diagnosis_khusus' => 'Tidak',
            'strong_kurus' => '0',
            'strong_penurunan_bb' => '0',
            'strong_kondisi' => '0',
            'strong_penyakit' => '0',
            'form_data' => [
                'pengobatan' => [],
                'terapi' => [],
                'riwayat_obat' => [],
                'obat_digunakan' => [],
                'rekonsiliasi' => [],
                'kebutuhan_edukasi' => [],
                'metode_edukasi' => [],
                'edukasi_pemberian' => [],
                'asesmen' => [],
                'pelaksanaan' => []
            ]
        ];

        for ($i = 0; $i < 6; $i++) {
            $defaults['rm' . $i] = $rm[$i] ?? '-';
        }

        // Decode JSON fields if present in data
        foreach ($data as $k => $v) {
            if (is_string($v) && (strpos($v, '{') === 0 || strpos($v, '[') === 0)) {
                $dec = json_decode($v, true);
                if (json_last_error() === JSON_ERROR_NONE) {
                    $data[$k . '_arr'] = $dec;
                    if ($k === 'form_data') $data['form_data'] = $dec;
                    if ($k === 'json_detail_obat' || $k === 'detail_obat') $data['detail_obat'] = $dec;
                }
            }
        }

        $merged = array_replace_recursive($defaults, $data);

        // Scan template file for missing keys and loop definitions
        $tplPath = $template;
        if (!file_exists($tplPath)) {
            $tplPath = BASE_DIR . '/plugins/form_rme/view/admin/' . ltrim($template, '/');
        }

        if (file_exists($tplPath)) {
            $tplContent = file_get_contents($tplPath);

            // Detect all loops: {loop: $var}
            if (preg_match_all('/{loop:\s*\$?([a-zA-Z0-9_\.]+)}/', $tplContent, $mLoop)) {
                foreach ($mLoop[1] as $loopVar) {
                    $parts = explode('.', $loopVar);
                    if (count($parts) === 1) {
                        $merged[$parts[0]] = is_array($merged[$parts[0]] ?? null) ? $merged[$parts[0]] : [];
                    } elseif (count($parts) === 2 && in_array($parts[0], ['data', 'd', 'p'])) {
                        $merged[$parts[1]] = is_array($merged[$parts[1]] ?? null) ? $merged[$parts[1]] : [];
                    } elseif (count($parts) === 3 && in_array($parts[0], ['data', 'd', 'p'])) {
                        if (!isset($merged[$parts[1]]) || !is_array($merged[$parts[1]])) {
                            $merged[$parts[1]] = [];
                        }
                        $merged[$parts[1]][$parts[2]] = is_array($merged[$parts[1]][$parts[2]] ?? null) ? $merged[$parts[1]][$parts[2]] : [];
                    }
                }
            }

            // Detect all in_array($needle, $haystack)
            if (preg_match_all('/in_array\([^,]+,\s*\$?([a-zA-Z0-9_\.]+)/', $tplContent, $mInArray)) {
                foreach ($mInArray[1] as $arrVar) {
                    $arrVar = preg_replace("/\?\?.*$/", "", $arrVar);
                    $parts = explode('.', $arrVar);
                    if (count($parts) === 1) {
                        $merged[$parts[0]] = is_array($merged[$parts[0]] ?? null) ? $merged[$parts[0]] : [];
                    } elseif (count($parts) === 2 && in_array($parts[0], ['data', 'd', 'p'])) {
                        $merged[$parts[1]] = is_array($merged[$parts[1]] ?? null) ? $merged[$parts[1]] : [];
                    } elseif (count($parts) === 3 && in_array($parts[0], ['data', 'd', 'p'])) {
                        if (!isset($merged[$parts[1]]) || !is_array($merged[$parts[1]])) {
                            $merged[$parts[1]] = [];
                        }
                        $merged[$parts[1]][$parts[2]] = is_array($merged[$parts[1]][$parts[2]] ?? null) ? $merged[$parts[1]][$parts[2]] : [];
                    }
                }
            }

            // Scan 2-level nested: $d.parent.child
            if (preg_match_all('/(?:\$data|\$d|\$p)\.([a-zA-Z0-9_]+)\.([a-zA-Z0-9_]+)/', $tplContent, $m)) {
                for ($k = 0; $k < count($m[0]); $k++) {
                    $parent = $m[1][$k];
                    $child = $m[2][$k];
                    if (!isset($merged[$parent]) || !is_array($merged[$parent])) {
                        $merged[$parent] = [];
                    }
                    if (!isset($merged[$parent][$child])) {
                        $merged[$parent][$child] = '';
                    }
                }
            }

            // Scan 1-level: $data.key or $data["key"]
            if (preg_match_all('/(?:\$data|\$d|\$p)\[\x27([a-zA-Z0-9_]+)\x27\]/', $tplContent, $m)) {
                foreach ($m[1] as $k) {
                    if (!isset($merged[$k])) $merged[$k] = '';
                }
            }
            if (preg_match_all('/(?:\$data|\$d|\$p)\["([a-zA-Z0-9_]+)"\]/', $tplContent, $m)) {
                foreach ($m[1] as $k) {
                    if (!isset($merged[$k])) $merged[$k] = '';
                }
            }
            if (preg_match_all('/(?:\$data|\$d|\$p)\.([a-zA-Z0-9_]+)/', $tplContent, $m)) {
                foreach ($m[1] as $k) {
                    if (!isset($merged[$k])) $merged[$k] = '';
                }
            }
        }

        return $merged;
    }

    public function renderLiveCetakPreview($routeCetak)
    {
        @ini_set('display_errors', '0');

        $map = $this->getRmeFormMap();
        if (!isset($map[$routeCetak])) {
            echo "Formulir RME '$routeCetak' tidak ditemukan.";
            exit();
        }

        $info = $map[$routeCetak];
        $template = $info['template'];
        
        $data = !empty($_POST) ? $_POST : $_GET;
        $no_rawat = trim($data['no_rawat'] ?? ($_GET['no_rawat'] ?? ''));

        // 1. Lengkapi data pasien jika no_rawat ada
        if (!empty($no_rawat)) {
            $patient = $this->getPatientContext($no_rawat);
            if (!empty($patient)) {
                $patientFields = [
                    'no_rawat' => $no_rawat,
                    'no_rkm_medis' => $patient['no_rkm_medis'] ?? '',
                    'nm_pasien' => $patient['nm_pasien'] ?? '',
                    'nama_pasien' => $patient['nm_pasien'] ?? '',
                    'jk' => $patient['jk'] ?? '',
                    'jenis_kelamin' => $patient['jk'] ?? '',
                    'tgl_lahir' => $patient['tgl_lahir'] ?? '',
                    'tanggal_lahir' => $patient['tgl_lahir'] ?? '',
                    'tmp_lahir' => $patient['tmp_lahir'] ?? '',
                    'umur' => $patient['umur'] ?? '',
                    'alamat' => $patient['alamat'] ?? '',
                    'ruangan' => $patient['ruangan'] ?? '',
                    'nm_bangsal' => $patient['nm_bangsal'] ?? '',
                    'nm_poli' => $patient['nm_poli'] ?? '',
                    'dokter' => $patient['dokter'] ?? '',
                    'nm_dokter' => $patient['dokter'] ?? '',
                    'nama_dokter' => $patient['dokter'] ?? '',
                    'nip_dpjp' => $patient['kd_dokter'] ?? '',
                    'kd_dokter' => $patient['kd_dokter'] ?? '',
                    'diagnosa' => $patient['diagnosa'] ?? '',
                    'diagnosis_medis' => $patient['diagnosa'] ?? '',
                ];
                foreach ($patientFields as $pf => $pv) {
                    if (empty($data[$pf])) {
                        $data[$pf] = $pv;
                    }
                }
            }
        }

        $prepData = $this->prepareCetakData($data, $template);
        if ($template === 'ri15a/ri15a_cetak.html') {
            if (!isset($prepData['detail_obat']) || !is_array($prepData['detail_obat'])) {
                $prepData['detail_obat'] = [];
            }
            while (count($prepData['detail_obat']) < 15) {
                $prepData['detail_obat'][] = ['tgl_jam'=>'', 'nama'=>'', 'dosis'=>'', 'frekuensi'=>'', 'cara'=>'', 'antibiotik'=>'', 'ttd_dokter'=>'', 'stop_tgl_jam'=>'', 'stop_ttd_dokter'=>'', 'ket'=>''];
            }
        }
        $prepData['kop_img'] = !empty($_GET['pdf']) ? (defined('BASE_DIR') ? BASE_DIR . '/assets/img/KOP-SURAT.png' : url('assets/img/KOP-SURAT.png')) : url('assets/img/KOP-SURAT.png');
        $is_mpdf = !empty($_GET['pdf']) && $_GET['pdf'] == '1';

        $viewData = [
            'data' => $prepData,
            'd' => $prepData,
            'p' => $prepData,
            'rows' => $prepData['rows'],
            'katRows' => $prepData['katRows'],
            'p1' => $prepData['p1'],
            'p2' => $prepData['p2'],
            'detail' => $prepData['detail'],
            'detail_obat' => $prepData['detail_obat'],
            'pelaksanaan' => $prepData['pelaksanaan'],
            'pengkajian' => $prepData['pengkajian'],
            'asesmen' => $prepData['asesmen'],
            'dewasaColsLeft' => $prepData['dewasaColsLeft'],
            'dewasaColsRight' => $prepData['dewasaColsRight'],
            'h2Cols' => $prepData['h2Cols'],
            'form_data' => $prepData['form_data'],
            'kop_img' => $prepData['kop_img'],
            'is_mpdf' => $is_mpdf
        ];

        $html = $this->draw($template, $viewData);

        if ($is_mpdf) {
            $mpdf = new \Mpdf\Mpdf(['mode' => 'utf-8', 'format' => 'A4', 'margin_left' => 10, 'margin_right' => 10, 'margin_top' => 10, 'margin_bottom' => 10]);
            $mpdf->WriteHTML($html);
            if (ob_get_length()) {
                ob_clean();
            }
            $mpdf->Output($info['kode'] . '_' . ($prepData['no_rkm_medis'] ?? 'dokumen') . '.pdf', 'I');
            exit();
        }

        echo $html;
        exit();
    }


