    public function prepareFormData($tableName, $id, $no_rawat, array $defaultData = [], $primaryKey = 'id')
    {
        $data = $defaultData;
        $existing = null;

        if (!empty($id)) {
            $existing = $this->db($tableName)->where($primaryKey, $id)->oneArray();
        } elseif (!empty($no_rawat)) {
            $existing = $this->db($tableName)->where('no_rawat', $no_rawat)->desc($primaryKey)->oneArray();
        }

        if ($existing) {
            $data = array_merge($data, $existing);
            $id = $existing[$primaryKey];
        }

        $targetNoRawat = !empty($no_rawat) ? $no_rawat : ($data['no_rawat'] ?? '');
        $patient = $this->getPatientContext($targetNoRawat);

        if ($patient) {
            $data['no_rawat'] = $patient['no_rawat'];
            $data['no_rkm_medis'] = $patient['no_rkm_medis'];
            $data['nm_pasien'] = $patient['nm_pasien'];
            $data['jk'] = $patient['jk'];
            $data['jk_text'] = $patient['jk_text'];
            $data['tmp_lahir'] = $patient['tmp_lahir'];
            $data['tgl_lahir'] = $patient['tgl_lahir'];
            $data['umur'] = $patient['umur'];
            $data['alamat'] = $patient['alamat'];
            $data['no_ktp'] = $patient['no_ktp'];
            $data['no_tlp'] = $patient['no_tlp'];

            if (array_key_exists('ruangan', $data) && empty($data['ruangan'])) {
                $data['ruangan'] = $patient['ruangan'];
            }
            if (array_key_exists('dokter', $data) && empty($data['dokter'])) {
                $data['dokter'] = $patient['dokter'];
            }
            if (array_key_exists('kd_dokter', $data) && empty($data['kd_dokter'])) {
                $data['kd_dokter'] = $patient['kd_dokter'];
            }
            if (array_key_exists('nama_dokter', $data) && empty($data['nama_dokter'])) {
                $data['nama_dokter'] = $patient['dokter'];
            }
            if (array_key_exists('nip_dokter', $data) && empty($data['nip_dokter'])) {
                $data['nip_dokter'] = $patient['kd_dokter'];
            }
            if (array_key_exists('diagnosis_medis', $data) && empty($data['diagnosis_medis'])) {
                $data['diagnosis_medis'] = $patient['diagnosa'];
            }
            if (array_key_exists('diagnosa', $data) && empty($data['diagnosa'])) {
                $data['diagnosa'] = $patient['diagnosa'];
            }
            if (array_key_exists('diagnosa_dpjp', $data) && empty($data['diagnosa_dpjp'])) {
                $data['diagnosa_dpjp'] = $patient['diagnosa'];
            }
            if (array_key_exists('nama_pembuat', $data) && empty($data['nama_pembuat'])) {
                $data['nama_pembuat'] = !empty($patient['penanggung_jawab']) ? $patient['penanggung_jawab'] : $patient['nm_pasien'];
            }
            if (array_key_exists('hubungan', $data) && empty($data['hubungan'])) {
                $data['hubungan'] = !empty($patient['hubungan_pj']) ? $patient['hubungan_pj'] : 'Diri Sendiri';
            }
            if (array_key_exists('alamat_pembuat', $data) && empty($data['alamat_pembuat'])) {
                $data['alamat_pembuat'] = !empty($patient['alamat_pj']) ? $patient['alamat_pj'] : $patient['alamat'];
            }
        }

        return [$id, $data, $patient];
    }

    public function anyPasien($no_rawat = null)
    {
        $no_rawat = $no_rawat ?? ($_GET['no_rawat'] ?? ($_POST['no_rawat'] ?? ''));
        if (empty($no_rawat)) {
            $this->notify('warning', 'Pilih nomor rawat pasien terlebih dahulu.');
            redirect(url([ADMIN, 'rawat_jalan', 'manage']));
            exit();
        }

        $patient = $this->getPatientContext($no_rawat);
        if (empty($patient)) {
            $this->notify('danger', 'Data pasien dengan nomor rawat ' . htmlspecialchars($no_rawat) . ' tidak ditemukan.');
            redirect(url([ADMIN, 'rawat_jalan', 'manage']));
            exit();
        }

        $kd_poli = $patient['kd_poli'] ?? '';
        $isRanap = (!empty($patient['nm_bangsal']) || !empty($patient['kd_kamar']));

        $userId = $_SESSION['mlite_user'] ?? 1;
        $isAdmin = ($this->core->getUserInfo('access') == 'all') || ($this->core->getUserInfo('role', $userId) == 'admin') || ($userId == 1);

        // Ambil form sesuai unit poliklinik pasien
        $forms = [];
        if (!empty($kd_poli)) {
            $forms = $this->db('mlite_rme_unit_form')
                ->join('mlite_rme_form', 'mlite_rme_form.id = mlite_rme_unit_form.form_id')
                ->where('mlite_rme_unit_form.status', '1')
                ->where('mlite_rme_form.status', '1')
                ->where('mlite_rme_unit_form.kd_poli', $kd_poli)
                ->select('mlite_rme_form.*')
                ->asc('mlite_rme_form.kategori')
                ->asc('mlite_rme_form.urutan')
                ->toArray();
        }

        // Jika ranap, gabungkan juga form-form unit RANAP
        if ($isRanap) {
            $ranapForms = $this->db('mlite_rme_unit_form')
                ->join('mlite_rme_form', 'mlite_rme_form.id = mlite_rme_unit_form.form_id')
                ->where('mlite_rme_unit_form.status', '1')
                ->where('mlite_rme_form.status', '1')
                ->where('mlite_rme_unit_form.kd_poli', 'RANAP')
                ->select('mlite_rme_form.*')
                ->asc('mlite_rme_form.kategori')
                ->asc('mlite_rme_form.urutan')
                ->toArray();
            $existingIds = array_column($forms, 'id');
            foreach ($ranapForms as $rf) {
                if (!in_array($rf['id'], $existingIds)) {
                    $forms[] = $rf;
                }
            }
        }

        // Jika belum ada mapping form khusus unit ini atau admin, ambil semua form aktif
        if (empty($forms)) {
            $forms = $this->db('mlite_rme_form')
                ->where('status', '1')
                ->asc('kategori')
                ->asc('urutan')
                ->toArray();
        }

        // Periksa status pengisian untuk setiap form berdasarkan tabel database masing-masing
        $processedForms = [];
        $totalFilled = 0;

        foreach ($forms as $f) {
            $fillCount = 0;
            $lastRow = null;
            if (!empty($f['nama_tabel'])) {
                try {
                    $q = $this->db()->pdo()->prepare("SELECT * FROM `{$f['nama_tabel']}` WHERE `no_rawat` = ?");
                    $q->execute([$patient['no_rawat']]);
                    $entries = $q->fetchAll(\PDO::FETCH_ASSOC);
                    $fillCount = count($entries);
                    if ($fillCount > 0) {
                        if (isset($entries[0]['id'])) {
                            usort($entries, function ($a, $b) {
                                return ($b['id'] ?? 0) <=> ($a['id'] ?? 0);
                            });
                        }
                        $lastRow = $entries[0];
                        $totalFilled++;
                    }
                } catch (\Throwable $e) {
                }
            }

            $f['is_filled'] = ($fillCount > 0);
            $f['fill_count'] = $fillCount;
            $f['last_entry'] = $lastRow;
            $f['url_form'] = url([ADMIN, 'form_rme', $f['route_form']]) . '&no_rawat=' . urlencode($patient['no_rawat']);
            $f['url_manage'] = !empty($f['route_manage']) ? url([ADMIN, 'form_rme', $f['route_manage']]) . '&no_rawat=' . urlencode($patient['no_rawat']) : '';
            $routeCetak = !empty($f['route_cetak']) ? $f['route_cetak'] : str_replace('form', 'cetak', $f['route_form']);
            $rowId = $lastRow['id'] ?? '';
            $f['url_cetak'] = url([ADMIN, 'form_rme', $routeCetak]) . (!empty($rowId) ? "&id={$rowId}" : '') . '&no_rawat=' . urlencode($patient['no_rawat']);

            $processedForms[] = $f;
        }

        $totalForms = count($processedForms);
        $totalUnfilled = $totalForms - $totalFilled;
        $completionPct = $totalForms > 0 ? round(($totalFilled / $totalForms) * 100) : 0;

        $rolesMeta = $this->getAvailableClinicalRoles();
        $roleCounts = [];
        foreach (array_keys($rolesMeta) as $rk) {
            $roleCounts[$rk] = 0;
        }

        foreach ($processedForms as &$pf) {
            $pf['target_aktor'] = !empty($pf['target_aktor']) ? $pf['target_aktor'] : 'medis,paramedis';
            $pf['roles_list'] = array_filter(array_map('trim', explode(',', $pf['target_aktor'])));
            $assigned = [];
            foreach ($rolesMeta as $rk => $rm) {
                if (in_array($rk, $pf['roles_list'], true)) {
                    $assigned[] = $rm;
                    if (isset($roleCounts[$rk])) {
                        $roleCounts[$rk]++;
                    }
                }
            }
            $pf['assigned_roles_meta'] = $assigned;
        }
        unset($pf);

        // Kelompokkan form berdasarkan kategori
        $categories = [];
        foreach ($processedForms as $pf) {
            $cat = !empty($pf['kategori']) ? $pf['kategori'] : 'Umum';
            if (!isset($categories[$cat])) {
                $categories[$cat] = [
                    'nama' => $cat,
                    'total' => 0,
                    'filled' => 0,
                    'forms' => []
                ];
            }
            $categories[$cat]['forms'][] = $pf;
            $categories[$cat]['total']++;
            if ($pf['is_filled']) {
                $categories[$cat]['filled']++;
            }
        }

        // Ambil data perjalanan klinis lengkap dari datang sampai pulang
        $timeline = $this->getTimelineData($patient['no_rawat']);
        $filledForms = array_values(array_filter($processedForms, function ($f) {
            return !empty($f['is_filled']);
        }));

        return $this->draw('rme/pasien.html', [
            'patient' => $patient,
            'timeline' => $timeline,
            'filled_forms' => $filledForms,
            'forms' => $processedForms,
            'categories' => $categories,
            'total_forms' => $totalForms,
            'total_filled' => $totalFilled,
            'total_unfilled' => $totalUnfilled,
            'completion_pct' => $completionPct,
            'available_roles' => $rolesMeta,
            'role_counts' => $roleCounts,
            'user_role' => $this->getCurrentUserClinicalRole(),
            'is_admin' => $isAdmin,
            'is_ranap' => $isRanap,
            'token' => $_SESSION['token'] ?? ''
        ]);
    }

    public function getTimelineData($no_rawat)
    {
        if (empty($no_rawat)) {
            return [];
        }

        $pdo = $this->db()->pdo();

        // 1. Data Registrasi Pasien (Admisi)
        $reg = $this->db('reg_periksa')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
            ->leftJoin('poliklinik', 'poliklinik.kd_poli = reg_periksa.kd_poli')
            ->leftJoin('dokter', 'dokter.kd_dokter = reg_periksa.kd_dokter')
            ->leftJoin('penjab', 'penjab.kd_pj = reg_periksa.kd_pj')
            ->where('reg_periksa.no_rawat', $no_rawat)
            ->select('reg_periksa.*, pasien.nm_pasien, pasien.jk, pasien.tgl_lahir, pasien.umur, pasien.alamat, poliklinik.nm_poli, dokter.nm_dokter as dokter_reg, penjab.png_jawab')
            ->oneArray();

        if (!$reg) {
            return [];
        }

        // 2. Data Rawat Inap (Kamar & Bangsal) jika ada
        $kamarInap = [];
        try {
            $kamarInap = $this->db('kamar_inap')
                ->leftJoin('kamar', 'kamar.kd_kamar = kamar_inap.kd_kamar')
                ->leftJoin('bangsal', 'bangsal.kd_bangsal = kamar.kd_bangsal')
                ->where('kamar_inap.no_rawat', $no_rawat)
                ->desc('kamar_inap.tgl_masuk')
                ->desc('kamar_inap.jam_masuk')
                ->select('kamar_inap.*, bangsal.nm_bangsal, kamar.kd_kamar')
                ->toArray();
        } catch (\Throwable $e) {}

        // 3. SOAP / CPPT Ralan & Ranap
        $soapList = [];
        try {
            $stmt = $pdo->prepare("SELECT pr.*, peg.nama as petugas, 'Rawat Jalan' as unit_layanan 
                FROM pemeriksaan_ralan pr 
                LEFT JOIN pegawai peg ON peg.nik = pr.nip 
                WHERE pr.no_rawat = ? 
                ORDER BY pr.tgl_perawatan ASC, pr.jam_rawat ASC");
            $stmt->execute([$no_rawat]);
            $soapList = array_merge($soapList, $stmt->fetchAll(\PDO::FETCH_ASSOC));
        } catch (\Throwable $e) {}

        try {
            $stmt = $pdo->prepare("SELECT pr.*, peg.nama as petugas, 'Rawat Inap' as unit_layanan 
                FROM pemeriksaan_ranap pr 
                LEFT JOIN pegawai peg ON peg.nik = pr.nip 
                WHERE pr.no_rawat = ? 
                ORDER BY pr.tgl_perawatan ASC, pr.jam_rawat ASC");
            $stmt->execute([$no_rawat]);
            $soapList = array_merge($soapList, $stmt->fetchAll(\PDO::FETCH_ASSOC));
        } catch (\Throwable $e) {}

        // 4. Diagnosa ICD-10 & Prosedur ICD-9
        $diagnosa = [];
        try {
            $stmt = $pdo->prepare("SELECT d.*, p.nm_penyakit 
                FROM diagnosa_pasien d 
                JOIN penyakit p ON p.kd_penyakit = d.kd_penyakit 
                WHERE d.no_rawat = ? 
                ORDER BY d.prioritas ASC");
            $stmt->execute([$no_rawat]);
            $diagnosa = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        } catch (\Throwable $e) {}

        $prosedur = [];
        try {
            $stmt = $pdo->prepare("SELECT pr.*, icd.deskripsi_panjang 
                FROM prosedur_pasien pr 
                JOIN icd9 icd ON icd.kode = pr.kode 
                WHERE pr.no_rawat = ? 
                ORDER BY pr.prioritas ASC");
            $stmt->execute([$no_rawat]);
            $prosedur = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        } catch (\Throwable $e) {}

        // 5. Tindakan Ralan & Ranap
        $tindakan = [];
        try {
            $stmt = $pdo->prepare("
                (SELECT r.tgl_perawatan, r.jam_rawat, j.nm_perawatan, d.nm_dokter as pelaksana, 'Dokter' as peran, r.biaya_rawat 
                 FROM rawat_jl_dr r 
                 JOIN jns_perawatan j ON j.kd_jenis_prw = r.kd_jenis_prw 
                 JOIN dokter d ON d.kd_dokter = r.kd_dokter 
                 WHERE r.no_rawat = ?)
                UNION ALL
                (SELECT r.tgl_perawatan, r.jam_rawat, j.nm_perawatan, p.nama as pelaksana, 'Petugas/Perawat' as peran, r.biaya_rawat 
                 FROM rawat_jl_pr r 
                 JOIN jns_perawatan j ON j.kd_jenis_prw = r.kd_jenis_prw 
                 LEFT JOIN petugas p ON p.nip = r.nip 
                 WHERE r.no_rawat = ?)
                UNION ALL
                (SELECT r.tgl_perawatan, r.jam_rawat, j.nm_perawatan, CONCAT(d.nm_dokter, ' & ', COALESCE(p.nama, '')) as pelaksana, 'Dokter & Petugas' as peran, r.biaya_rawat 
                 FROM rawat_jl_drpr r 
                 JOIN jns_perawatan j ON j.kd_jenis_prw = r.kd_jenis_prw 
                 JOIN dokter d ON d.kd_dokter = r.kd_dokter 
                 LEFT JOIN petugas p ON p.nip = r.nip 
                 WHERE r.no_rawat = ?)
                UNION ALL
                (SELECT r.tgl_perawatan, r.jam_rawat, j.nm_perawatan, d.nm_dokter as pelaksana, 'Dokter Ranap' as peran, r.biaya_rawat 
                 FROM rawat_inap_dr r 
                 JOIN jns_perawatan_inap j ON j.kd_jenis_prw = r.kd_jenis_prw 
                 JOIN dokter d ON d.kd_dokter = r.kd_dokter 
                 WHERE r.no_rawat = ?)
                UNION ALL
                (SELECT r.tgl_perawatan, r.jam_rawat, j.nm_perawatan, p.nama as pelaksana, 'Petugas Ranap' as peran, r.biaya_rawat 
                 FROM rawat_inap_pr r 
                 JOIN jns_perawatan_inap j ON j.kd_jenis_prw = r.kd_jenis_prw 
                 LEFT JOIN petugas p ON p.nip = r.nip 
                 WHERE r.no_rawat = ?)
                ORDER BY tgl_perawatan ASC, jam_rawat ASC
            ");
            $stmt->execute([$no_rawat, $no_rawat, $no_rawat, $no_rawat, $no_rawat]);
            $tindakan = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        } catch (\Throwable $e) {}

        // 6. Laboratorium
        $labList = [];
        try {
            $stmt = $pdo->prepare("
                SELECT pl.tgl_periksa, pl.jam, pl.kd_jenis_prw, j.nm_perawatan, d.nm_dokter as dokter_perujuk, pl.kategori 
                FROM periksa_lab pl 
                LEFT JOIN jns_perawatan_lab j ON j.kd_jenis_prw = pl.kd_jenis_prw 
                LEFT JOIN dokter d ON d.kd_dokter = pl.dokter_perujuk 
                WHERE pl.no_rawat = ? 
                GROUP BY pl.tgl_periksa, pl.jam, pl.kd_jenis_prw 
                ORDER BY pl.tgl_periksa ASC, pl.jam ASC
            ");
            $stmt->execute([$no_rawat]);
            $labRows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

            foreach ($labRows as $lRow) {
                $detailStmt = $pdo->prepare("
                    SELECT dl.nilai, dl.nilai_rujukan, dl.keterangan, tl.Pemeriksaan, tl.satuan 
                    FROM detail_periksa_lab dl 
                    LEFT JOIN template_laboratorium tl ON tl.id_template = dl.id_template 
                    WHERE dl.no_rawat = ? AND dl.kd_jenis_prw = ? AND dl.tgl_periksa = ? AND dl.jam = ?
                ");
                $detailStmt->execute([$no_rawat, $lRow['kd_jenis_prw'], $lRow['tgl_periksa'], $lRow['jam']]);
                $lRow['details'] = $detailStmt->fetchAll(\PDO::FETCH_ASSOC);
                $labList[] = $lRow;
            }
        } catch (\Throwable $e) {}

        // 7. Radiologi
        $radList = [];
        try {
            $stmt = $pdo->prepare("
                SELECT pr.tgl_periksa, pr.jam, pr.kd_jenis_prw, j.nm_perawatan, d.nm_dokter as dokter_perujuk, 
                       hr.hasil as hasil_ekspertise 
                FROM periksa_radiologi pr 
                LEFT JOIN jns_perawatan_radiologi j ON j.kd_jenis_prw = pr.kd_jenis_prw 
                LEFT JOIN dokter d ON d.kd_dokter = pr.dokter_perujuk 
                LEFT JOIN hasil_radiologi hr ON (hr.no_rawat = pr.no_rawat AND hr.tgl_periksa = pr.tgl_periksa AND hr.jam = pr.jam) 
                WHERE pr.no_rawat = ? 
                GROUP BY pr.tgl_periksa, pr.jam, pr.kd_jenis_prw 
                ORDER BY pr.tgl_periksa ASC, pr.jam ASC
            ");
            $stmt->execute([$no_rawat]);
            $radList = $stmt->fetchAll(\PDO::FETCH_ASSOC);
        } catch (\Throwable $e) {}

        // 8. Resep & Obat
        $resepList = [];
        try {
            $stmt = $pdo->prepare("
                SELECT ro.no_resep, ro.tgl_peresepan, ro.jam_peresepan, ro.tgl_perawatan, ro.jam, ro.status, d.nm_dokter 
                FROM resep_obat ro 
                LEFT JOIN dokter d ON d.kd_dokter = ro.kd_dokter 
                WHERE ro.no_rawat = ? 
                ORDER BY ro.tgl_peresepan ASC, ro.jam_peresepan ASC
            ");
            $stmt->execute([$no_rawat]);
            $resepRows = $stmt->fetchAll(\PDO::FETCH_ASSOC);

            foreach ($resepRows as $rRow) {
                $itemStmt = $pdo->prepare("
                    SELECT rd.jml, rd.aturan_pakai, b.nama_brng, b.kode_sat 
                    FROM resep_dokter rd 
                    JOIN databarang b ON b.kode_brng = rd.kode_brng 
                    WHERE rd.no_resep = ?
                ");
                $itemStmt->execute([$rRow['no_resep']]);
                $rRow['items'] = $itemStmt->fetchAll(\PDO::FETCH_ASSOC);
                $resepList[] = $rRow;
            }
        } catch (\Throwable $e) {}

        return [
            'reg' => $reg,
            'kamar_inap' => $kamarInap,
            'soap' => $soapList,
            'diagnosa' => $diagnosa,
            'prosedur' => $prosedur,
            'tindakan' => $tindakan,
            'lab' => $labList,
            'radiologi' => $radList,
            'resep' => $resepList,
            'total_soap' => count($soapList),
            'total_diagnosa' => count($diagnosa),
            'total_prosedur' => count($prosedur),
            'total_tindakan' => count($tindakan),
            'total_lab' => count($labList),
            'total_radiologi' => count($radList),
            'total_resep' => count($resepList)
        ];
    }

    public function anyCetakberkas($no_rawat = null)
    {
        $no_rawat = $no_rawat ?? ($_GET['no_rawat'] ?? ($_POST['no_rawat'] ?? ''));
        if (empty($no_rawat)) {
            $this->notify('warning', 'Pilih nomor rawat pasien terlebih dahulu.');
            redirect(url([ADMIN, 'rawat_jalan', 'manage']));
            exit();
        }

        $patient = $this->getPatientContext($no_rawat);
        if (empty($patient)) {
            $this->notify('danger', 'Data pasien tidak ditemukan.');
            redirect(url([ADMIN, 'rawat_jalan', 'manage']));
            exit();
        }

        $timeline = $this->getTimelineData($patient['no_rawat']);

        // Ambil form RME yang terisi
        $allForms = $this->db('mlite_rme_form')->where('status', '1')->toArray();
        $filledForms = [];
        foreach ($allForms as $f) {
            if (!empty($f['nama_tabel'])) {
                try {
                    $q = $this->db()->pdo()->prepare("SELECT * FROM `{$f['nama_tabel']}` WHERE `no_rawat` = ?");
                    $q->execute([$patient['no_rawat']]);
                    $entries = $q->fetchAll(\PDO::FETCH_ASSOC);
                    if (!empty($entries)) {
                        if (isset($entries[0]['id'])) {
                            usort($entries, function ($a, $b) {
                                return ($b['id'] ?? 0) <=> ($a['id'] ?? 0);
                            });
                        }
                        $f['entries'] = $entries;
                        $routeCetak = !empty($f['route_cetak']) ? $f['route_cetak'] : str_replace('form', 'cetak', $f['route_form']);
                        $rowId = $entries[0]['id'] ?? '';
                        $f['url_cetak'] = url([ADMIN, 'form_rme', $routeCetak]) . (!empty($rowId) ? '&id=' . $rowId : '') . '&no_rawat=' . urlencode($patient['no_rawat']);
                        $filledForms[] = $f;
                    }
                } catch (\Throwable $e) {}
            }
        }

        $settings = $this->settings('settings');

        echo $this->draw('rme/cetak_berkas.html', [
            'patient' => $patient,
            'timeline' => $timeline,
            'filled_forms' => $filledForms,
            'settings' => $settings
        ]);
        exit();
    }

    public function renderDropdownMenu($row)
    {
        $no_rawat = $row["no_rawat"] ?? "";
        $no_rkm_medis = $row["no_rkm_medis"] ?? "";
        $kd_poli = $row["kd_poli"] ?? "";
        if (empty($kd_poli) && (!empty($row["kd_bangsal"]) || !empty($row["kd_kamar"]) || !empty($row["tgl_masuk"]))) {
            $kd_poli = "RANAP";
        }

        $userId = $_SESSION["mlite_user"] ?? 1;
        $isAdmin = ($this->core->getUserInfo("access") == "all") || ($this->core->getUserInfo("role", $userId) == "admin") || ($userId == 1);

        $forms = [];
        if (!empty($kd_poli)) {
            $forms = $this->db("mlite_rme_unit_form")
                ->join("mlite_rme_form", "mlite_rme_form.id = mlite_rme_unit_form.form_id")
                ->where("mlite_rme_unit_form.status", "1")
                ->where("mlite_rme_form.status", "1")
                ->where("mlite_rme_unit_form.kd_poli", $kd_poli)
                ->select("mlite_rme_form.*")
                ->asc("mlite_rme_form.kategori")
                ->asc("mlite_rme_form.urutan")
                ->toArray();
        }

        if (empty($forms) || $isAdmin) {
            $all = $this->db("mlite_rme_form")
                ->where("status", "1")
                ->asc("kategori")
                ->asc("urutan")
                ->toArray();
            if (empty($forms)) {
                $forms = $all;
            }
        }

        if (empty($forms)) {
            return;
        }

        // Cache filled status and existing row ID for quick-print
        $filledMap = [];
        $idMap = [];
        if (!empty($no_rawat)) {
            foreach ($forms as $f) {
                if (!empty($f["nama_tabel"])) {
                    try {
                        $chk = $this->db()->pdo()->prepare("SELECT * FROM `{$f["nama_tabel"]}` WHERE `no_rawat` = ? LIMIT 1");
                        $chk->execute([$no_rawat]);
                        $foundRow = $chk->fetch(\PDO::FETCH_ASSOC);
                        if (!empty($foundRow)) {
                            $filledMap[$f["id"]] = true;
                            $idMap[$f["id"]] = $foundRow["id"] ?? "";
                        } else {
                            $filledMap[$f["id"]] = false;
                        }
                    } catch (\Exception $e) {
                        $filledMap[$f["id"]] = false;
                    }
                }
            }
        }

        $totalFilled = count(array_filter($filledMap));
        $totalCount = count($forms);
        $pasienUrl = url([ADMIN, "form_rme", "pasien"]) . "&no_rawat=" . urlencode($no_rawat);
        $badgeBg = $totalFilled > 0 ? "#10b981" : "#64748b";

        echo "<li style=\"border-bottom: 1px solid #e2e8f0; margin-bottom: 2px;\">";
        echo "  <a href=\"{$pasienUrl}\" style=\"background: #eff6ff !important; color: #1d4ed8 !important; font-weight: 600 !important; border-left: 3px solid #0284c7; display: flex !important; align-items: center !important; justify-content: space-between !important; padding: 6px 10px !important; font-size: 11px !important; text-transform: uppercase;\">";
        echo "    <span style=\"white-space: nowrap;\">Lembar Kerja Form RME</span>";
        echo "    <span class=\"badge\" style=\"background: {$badgeBg} !important; color: #ffffff !important; font-size: 9px !important; font-weight: 700 !important; padding: 2px 5px !important; border-radius: 4px !important; margin-left: 6px !important; flex-shrink: 0;\">{$totalFilled}/{$totalCount}</span>";
        echo "  </a>";
        echo "</li>";
    }

