            redirect(url([ADMIN, 'form_rme', 'pelayanankerohanianmanage']));
        }

        $reg = $this->db('reg_periksa')->where('no_rawat', $no_rawat)->oneArray();
        $no_rkm_medis = $reg['no_rkm_medis'] ?? ($_POST['no_rkm_medis'] ?? '');

        $saveData = [
            'no_rawat' => $no_rawat,
            'no_rkm_medis' => $no_rkm_medis,
