            'nama_perawat' => $_POST['nama_perawat'] ?? '',
            'nip_perawat' => $_POST['nip_perawat'] ?? '',
            'catatan' => $_POST['catatan'] ?? ''
        ];

        if ($id) {
            $saveData['updated_at'] = date('Y-m-d H:i:s');
