                ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_lampiran_konsultasi_internal.no_rawat')
                ->leftJoin('pasien', 'pasien.no_rkm_medis = COALESCE(rm_lampiran_konsultasi_internal.no_rkm_medis, reg_periksa.no_rkm_medis)')
