            $saveData['created_at'] = date('Y-m-d H:i:s');
            $result = $this->db('rm_lampiran_surat_pernyataan_bersedia_menunggu')->save($saveData);
            $msg = 'disimpan';
        }

        if ($result) {
            $this->setNotify('success', "Surat Pernyataan Bersedia Menunggu berhasil $msg.");
        } else {
            $this->setNotify('failure', "Gagal menyimpan surat pernyataan bersedia menunggu.");
        }

        redirect(url([ADMIN, 'form_rme', 'bersediamenunggumanage']));
    }

