        $intervensi_konselor = isset($_POST['intervensi']) && is_array($_POST['intervensi']) ? json_encode($_POST['intervensi']) : ($_POST['intervensi_konselor'] ?? '');

        $payload = [
            'no_rawat' => $no_rawat,
            'no_rkm_medis' => $_POST['no_rkm_medis'] ?? '',
            'kode_klien' => $_POST['kode_klien'] ?? '',
