    public function anyManage()
    {
        if (isset($_GET['action']) && $_GET['action'] == 'delete' && !empty($_GET['no_rawat'])) {
            $no_rawat = $_GET['no_rawat'];
            try { $this->db('rm_asesmen_keperawatan_gigi_ugd')->where('no_rawat', $no_rawat)->delete(); } catch (\Exception $e) {}
            try { $this->db('asesmen_keperawatan_gigi_ugd')->where('no_rawat', $no_rawat)->delete(); } catch (\Exception $e) {}
            $this->notify('success', 'Data berhasil dihapus');
            redirect(url([ADMIN, 'form_rme', 'akgmumanage']));
        }

        $this->core->addCSS(url('assets/css/dataTables.bootstrap.min.css'));
        $this->core->addJS(url('assets/jscripts/jquery.dataTables.min.js'));
        $this->core->addJS(url('assets/jscripts/dataTables.bootstrap.min.js'));

        $asesmen = $this->db('rm_asesmen_keperawatan_gigi_ugd')
            ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_asesmen_keperawatan_gigi_ugd.no_rawat')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
            ->select('rm_asesmen_keperawatan_gigi_ugd.*, pasien.nm_pasien, pasien.nm_pasien as nama_pasien, reg_periksa.no_rkm_medis')
            ->desc('rm_asesmen_keperawatan_gigi_ugd.tanggal')
            ->toArray();

        return $this->draw('akgmu/manage.html', ['asesmen' => $asesmen]);
    }

    public function getForm()
    {
        $no_rawat = $_GET['no_rawat'] ?? '';
        $data = $this->db('rm_asesmen_keperawatan_gigi_ugd')->where('no_rawat', $no_rawat)->oneArray();

        // Jika ada no_rawat, coba ambil data pasien dari relasi untuk pre-fill
        if (!empty($no_rawat)) {
            $reg = $this->db('reg_periksa')
                ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
                ->where('reg_periksa.no_rawat', $no_rawat)
                ->select('reg_periksa.no_rkm_medis, pasien.nm_pasien, pasien.nm_pasien as nama_pasien, pasien.jk, pasien.tgl_lahir')
                ->oneArray();

            if ($reg) {
                // Hanya isi jika belum ada di data asesmen
                if (empty($data['nama_pasien']))   $data['nama_pasien']   = $reg['nm_pasien'] ?? '';
                if (empty($data['jenis_kelamin'])) $data['jenis_kelamin'] = $reg['jk'] ?? '';
                if (empty($data['tanggal_lahir'])) $data['tanggal_lahir'] = $reg['tgl_lahir'] ?? '';
                $data['no_rkm_medis'] = $reg['no_rkm_medis'] ?? '';
            }
        }

        return $this->draw('akgmu/form.html', ['data' => $data, 'no_rawat' => $no_rawat]);
    }

    // AJAX: ambil info pasien berdasarkan no_rawat
    public function anyPatientinfo()
    {
        $no_rawat = $_GET['no_rawat'] ?? '';
        $no_rawat = trim($no_rawat);
        
        // Jika input hanya angka dan kurang dari 6 digit, otomatis tambahkan nol di depan (format standar No RM)
        if (is_numeric($no_rawat) && strlen($no_rawat) < 6) {
            $no_rawat = str_pad($no_rawat, 6, '0', STR_PAD_LEFT);
        }

        $result = ['success' => false];

        if (!empty($no_rawat)) {
            $reg = $this->db('reg_periksa')
                ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
                ->where('reg_periksa.no_rawat', $no_rawat)
                ->orWhere('reg_periksa.no_rkm_medis', $no_rawat)
                ->select('reg_periksa.no_rawat, reg_periksa.no_rkm_medis, pasien.nm_pasien, pasien.nm_pasien as nama_pasien, pasien.jk, pasien.tgl_lahir')
                ->desc('reg_periksa.tgl_registrasi')
                ->desc('reg_periksa.jam_reg')
                ->oneArray();

            if ($reg) {
                $result = [
                    'success'       => true,
                    'no_rawat'      => $reg['no_rawat'] ?? '',
                    'nama_pasien'   => $reg['nm_pasien'] ?? '',
                    'jenis_kelamin' => $reg['jk'] ?? '',
                    'tanggal_lahir' => $reg['tgl_lahir'] ?? '',
                    'no_rkm_medis'  => $reg['no_rkm_medis'] ?? '',
                ];
            }
        }

        header('Content-Type: application/json');
        echo json_encode($result);
        exit();
    }

    public function postSave()
    {
        $data = $_POST;
        if (isset($data['no_rawat'])) {
            $cek = $this->db('rm_asesmen_keperawatan_gigi_ugd')->where('no_rawat', $data['no_rawat'])->oneArray();
            if ($cek) {
                $this->db('rm_asesmen_keperawatan_gigi_ugd')->where('no_rawat', $data['no_rawat'])->save($data);
            } else {
                $data['tanggal'] = date('Y-m-d H:i:s');
                $this->db('rm_asesmen_keperawatan_gigi_ugd')->save($data);
            }
        }
        $this->notify('success', 'Data berhasil disimpan');
        redirect(url([ADMIN, 'form_rme', 'akgmumanage']));
    }

    public function anyCetak()
    {
        @ini_set('display_errors', '0');
        $no_rawat = $_POST['no_rawat'] ?? ($_GET['no_rawat'] ?? '');
        $data = [];

        // 1. Jika dikirim via POST (Live Preview langsung dari formulir yang sedang diisi):
        if (!empty($_POST)) {
            $data = $_POST;
            if (!empty($no_rawat)) {
                $reg = $this->db('reg_periksa')
                    ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
                    ->where('reg_periksa.no_rawat', $no_rawat)
                    ->orWhere('reg_periksa.no_rkm_medis', $no_rawat)
                    ->select('reg_periksa.no_rkm_medis, pasien.nm_pasien, pasien.jk as jenis_kelamin, pasien.tgl_lahir as tanggal_lahir')
                    ->oneArray();
                if ($reg) {
                    if (empty($data['no_rkm_medis'])) $data['no_rkm_medis'] = $reg['no_rkm_medis'];
                    if (empty($data['nama_pasien'])) $data['nama_pasien'] = $reg['nm_pasien'];
                    if (empty($data['jenis_kelamin'])) $data['jenis_kelamin'] = $reg['jenis_kelamin'];
                    if (empty($data['tanggal_lahir'])) $data['tanggal_lahir'] = $reg['tanggal_lahir'];
                }
            }
            if (empty($data['no_rkm_medis']) && !empty($no_rawat)) {
                $parts = explode('/', $no_rawat);
                $lastPart = end($parts);
                if (strlen($lastPart) == 6 && is_numeric($lastPart)) {
                    $data['no_rkm_medis'] = $lastPart;
                }
            }
        } else {
            // 2. Jika dibuka via GET (ambil dari database yang sudah tersimpan):
            if (!empty($no_rawat)) {
                $data = $this->db('rm_asesmen_keperawatan_gigi_ugd')
                    ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_asesmen_keperawatan_gigi_ugd.no_rawat')
                    ->leftJoin('dokter', 'dokter.kd_dokter = rm_asesmen_keperawatan_gigi_ugd.nip_dpjp')
                    ->leftJoin('petugas', 'petugas.nip = rm_asesmen_keperawatan_gigi_ugd.nip')
                    ->where('rm_asesmen_keperawatan_gigi_ugd.no_rawat', $no_rawat)
                    ->select('rm_asesmen_keperawatan_gigi_ugd.*, reg_periksa.no_rkm_medis, dokter.nm_dokter, petugas.nama AS nm_perawat')
                    ->oneArray();

                if (!$data) {
                    $data = [];
                    $reg = $this->db('reg_periksa')
                        ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
                        ->where('reg_periksa.no_rawat', $no_rawat)
                        ->select('reg_periksa.no_rawat, reg_periksa.no_rkm_medis, pasien.nm_pasien, pasien.nm_pasien as nama_pasien, pasien.jk as jenis_kelamin, pasien.tgl_lahir as tanggal_lahir')
                        ->oneArray();
                    if ($reg) {
                        $data = $reg;
                    }
                }
            } else {
                // Jika no_rawat kosong dan belum ada asesmen tersimpan, cari data pasien terkini sebagai contoh preview
                $latest = $this->db('rm_asesmen_keperawatan_gigi_ugd')
                    ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_asesmen_keperawatan_gigi_ugd.no_rawat')
                    ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
                    ->leftJoin('dokter', 'dokter.kd_dokter = rm_asesmen_keperawatan_gigi_ugd.nip_dpjp')
                    ->leftJoin('petugas', 'petugas.nip = rm_asesmen_keperawatan_gigi_ugd.nip')
                    ->select('rm_asesmen_keperawatan_gigi_ugd.*, reg_periksa.no_rkm_medis, pasien.nm_pasien, dokter.nm_dokter, petugas.nama AS nm_perawat')
                    ->desc('rm_asesmen_keperawatan_gigi_ugd.tanggal')
                    ->oneArray();
                if ($latest) {
                    $data = $latest;
                }
            }
        }

        // Ambil nama dokter dan perawat jika belum ada
        if (!empty($data['nip_dpjp']) && empty($data['nm_dokter'])) {
            $dok = $this->db('dokter')->where('kd_dokter', $data['nip_dpjp'])->oneArray();
            if ($dok) $data['nm_dokter'] = $dok['nm_dokter'];
        }
        if (!empty($data['nip']) && empty($data['nm_perawat'])) {
            $pet = $this->db('petugas')->where('nip', $data['nip'])->oneArray();
            if ($pet) $data['nm_perawat'] = $pet['nama'];
        }

        // Fallback no_rkm_medis
        if (empty($data['no_rkm_medis'])) {
            $data['no_rkm_medis'] = '';
        }

        // Format tanggal lahir ke format Indonesia
        if (!empty($data['tanggal_lahir'])) {
            $bulan = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
                      'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
            $tgl = explode('-', $data['tanggal_lahir']);
            if (count($tgl) == 3) {
                $data['tanggal_lahir_indo'] = (int)$tgl[2] . ' ' . $bulan[(int)$tgl[1]] . ' ' . $tgl[0];
            } else {
                $data['tanggal_lahir_indo'] = $data['tanggal_lahir'];
            }
        }

        $data['kop_img'] = !empty($_GET['pdf']) ? (defined('BASE_DIR') ? BASE_DIR . '/assets/img/KOP-SURAT.png' : url('assets/img/KOP-SURAT.png')) : url('assets/img/KOP-SURAT.png');
        $is_mpdf = !empty($_GET['pdf']) && $_GET['pdf'] == '1';
        $html = $this->draw('akgmu/cetak.html', ['data' => $data, 'kop_img' => $data['kop_img'], 'is_mpdf' => $is_mpdf]);
        if ($is_mpdf) {
@ini_set('display_errors', '0');
            $mpdf = new \Mpdf\Mpdf(['mode' => 'utf-8', 'format' => 'A4', 'margin_left' => 10, 'margin_right' => 10, 'margin_top' => 10, 'margin_bottom' => 10]);
            $mpdf->WriteHTML($html);
if (ob_get_length()) {
    ob_clean();
}
            $mpdf->Output('RM_GD4_' . ($data['no_rkm_medis'] ?? 'dokumen') . '.pdf', 'I');
            exit();
        }
        echo $html;
        exit();
    }

