            ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_bm1_informasi_tindakan.no_rawat')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = reg_periksa.no_rkm_medis')
            ->where('rm_bm1_informasi_tindakan.id', $id)
