            $d2 = $this->db('petugas')->like('nama', "%$q%")->orLike('nip', "%$q%")->limit(10)->select('nip as id, nama as text')->toArray();
            ob_clean(); echo json_encode(['results' => array_merge($d1, $d2)]); exit();
        }
        
        // AJAX: ambil info pasien
        if (isset($_GET['ajax_patient'])) {
