    public function postRi04save() {
        $id = $_POST['id'] ?? '';
        $data = $_POST; 
        unset($data['id']); unset($data['t']); unset($data['ajax_patient']); unset($data['save']);
        
        foreach(['alat_terpasang', 'obat_dibawa', 'dokumen_disertakan', 'informasi_diberikan'] as $f) {
            $json_val = $_POST['json_' . $f] ?? '[]';
            $data[$f] = $json_val;
            unset($data['json_' . $f]);
            unset($data[$f . '_raw']);
