        if ($id) { $this->db('rm_ri04_transfer_internal')->where('id', $id)->save($data); $this->notify('success', 'Data diupdate'); } 
        else { $this->db('rm_ri04_transfer_internal')->save($data); $this->notify('success', 'Data ditambahkan'); }
