            return $this->renderLiveCetakPreview('ri18cetak');
        }

        $d['pengkajian'] = !empty($d['pengkajian']) && is_string($d['pengkajian']) ? json_decode($d['pengkajian'], true) : [];
        if (!is_array($d['pengkajian'])) { $d['pengkajian'] = []; }
