        if (!is_array($d['pelaksanaan'])) { $d['pelaksanaan'] = []; }

        while(count($d['pelaksanaan']) < 8) {
            $d['pelaksanaan'][] = ['tgl_jam'=>'', 'isi'=>'', 'pra_edukasi'=>'', 'penerima'=>'', 'metode'=>'', 'evaluasi'=>'', 'profesi'=>'', 'nama_pemberi'=>'', 'nama_penerima'=>''];
