    // ============================================================
    // LAMPIRAN - FORMULIR PROFIL RINGKAS MEDIS RAWAT JALAN (PRMRJ)
    // ============================================================

    public function anyPrmrjmanage()
    {
        $this->core->addCSS(url('assets/css/dataTables.bootstrap.min.css'));
        $this->core->addJS(url('assets/jscripts/jquery.dataTables.min.js'));
        $this->core->addJS(url('assets/jscripts/dataTables.bootstrap.min.js'));

        $rows = $this->db('rm_lampiran_profil_ringkas_medis_rajal')
            ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_lampiran_profil_ringkas_medis_rajal.no_rawat')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = COALESCE(rm_lampiran_profil_ringkas_medis_rajal.no_rkm_medis, reg_periksa.no_rkm_medis)')
            ->select('rm_lampiran_profil_ringkas_medis_rajal.*, COALESCE(rm_lampiran_profil_ringkas_medis_rajal.no_rkm_medis, reg_periksa.no_rkm_medis) as no_rkm_medis, pasien.nm_pasien, pasien.jk')
            ->desc('rm_lampiran_profil_ringkas_medis_rajal.id')
            ->toArray();

        foreach ($rows as &$r) {
            $diag = !empty($r['diagnosa_dpjp']) ? json_decode($r['diagnosa_dpjp'], true) : [];
            $r['total_diagnosa'] = is_array($diag) ? count($diag) : 0;
            $alergi = !empty($r['riwayat_alergi']) ? json_decode($r['riwayat_alergi'], true) : [];
            $r['total_alergi'] = is_array($alergi) ? count($alergi) : 0;
            $obat = !empty($r['obat_obatan']) ? json_decode($r['obat_obatan'], true) : [];
            $r['total_obat'] = is_array($obat) ? count($obat) : 0;
        }

        return $this->draw('lampiran_prmrj/manage.html', ['data' => $rows]);
    }

