            'diagnosa_dpjp' => '[]', 'riwayat_alergi' => '[]', 'diagnosa_ranap' => '[]', 'operasi_tindakan' => '[]', 'obat_obatan' => '[]',
            'keterangan_tambahan' => '', 'nama_dokter' => '', 'nip_dokter' => ''
        ];

        list($id, $data) = $this->prepareFormData('rm_lampiran_profil_ringkas_medis_rajal', $id, $no_rawat, $defaultData);
        $dokter_list = $this->db('dokter')->select('kd_dokter, nm_dokter')->toArray();
