    public function getIntervensinyericetak($id = null)
    {
        @ini_set('display_errors', '0');
        $id = $id ?? ($_GET['id'] ?? '');
        $no_rawat = trim($_GET['no_rawat'] ?? '');
        if (empty($id) && !empty($no_rawat)) {
            $row = $this->db('rm_lampiran_intervensi_pengkajian_nyeri')->where('no_rawat', $no_rawat)->desc('id')->oneArray();
            if ($row) { $id = $row['id']; }
        }
        if (!$id) {
            return $this->renderLiveCetakPreview('intervensinyericetak');
        }

        $data = $this->db('rm_lampiran_intervensi_pengkajian_nyeri')
            ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = rm_lampiran_intervensi_pengkajian_nyeri.no_rawat')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = COALESCE(rm_lampiran_intervensi_pengkajian_nyeri.no_rkm_medis, reg_periksa.no_rkm_medis)')
            ->where('rm_lampiran_intervensi_pengkajian_nyeri.id', $id)
            ->select('rm_lampiran_intervensi_pengkajian_nyeri.*, COALESCE(rm_lampiran_intervensi_pengkajian_nyeri.no_rkm_medis, reg_periksa.no_rkm_medis) as no_rkm_medis, pasien.nm_pasien, pasien.jk, pasien.tmp_lahir, pasien.tgl_lahir, pasien.umur, pasien.alamat')
            ->oneArray();

        if (!$data) {
            return $this->renderLiveCetakPreview('intervensinyericetak');
        }

        $rmRaw = ltrim($data['no_rkm_medis'] ?? '', "'");
        $rm = str_pad($rmRaw, 6, '0', STR_PAD_LEFT);
        for ($i = 0; $i < 6; $i++) {
            $data['rm' . $i] = $rm[$i] ?? '&nbsp;';
        }
        $data['no_rkm_medis'] = $rm;

        $bulan = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
                  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];

        if (!empty($data['tgl_lahir']) && $data['tgl_lahir'] != '0000-00-00') {
            $tgl = explode('-', $data['tgl_lahir']);
            if (count($tgl) == 3) {
                $data['tgl_lahir_indo'] = (int)$tgl[2] . ' ' . $bulan[(int)$tgl[1]] . ' ' . $tgl[0];
            } else {
                $data['tgl_lahir_indo'] = $data['tgl_lahir'];
            }
        } else {
            $data['tgl_lahir_indo'] = '-';
        }

        // Decode list records
        $recordList = !empty($data['detail_pengkajian']) ? json_decode($data['detail_pengkajian'], true) : [];
        if (!is_array($recordList)) {
            $recordList = [];
        }

        // Standar baris minimal 20 baris agar pas 1 halaman A4 penuh presisi formulir fisik
        $targetRows = max(20, count($recordList));
        $paddedRecords = $recordList;
        while (count($paddedRecords) < $targetRows) {
            $paddedRecords[] = [
                'tgl_jam' => '&nbsp;',
                'skor_nyeri' => '&nbsp;',
                'td' => '&nbsp;',
                'nadi' => '&nbsp;',
                'napas' => '&nbsp;',
                'suhu' => '&nbsp;',
                'obat_nama' => '&nbsp;',
                'obat_dosis' => '&nbsp;',
                'obat_rute' => '&nbsp;',
                'non_farmakologi' => '&nbsp;',
                'petugas_nama' => '&nbsp;',
                'petugas_paraf' => '&nbsp;',
                'waktu_kaji_ulang' => '&nbsp;'
            ];
        }
        $data['record_rows'] = $paddedRecords;

        // Cek jika request export mPDF
        if (file_exists(BASE_DIR . '/vendor/autoload.php')) {
            require_once BASE_DIR . '/vendor/autoload.php';
        }
        if (isset($_GET['pdf']) && $_GET['pdf'] == '1' && class_exists('\Mpdf\Mpdf')) {
            try {
                $data['kop_img'] = BASE_DIR . '/assets/img/KOP-SURAT.png';
                $mpdf = new \Mpdf\Mpdf([
                    'mode' => 'utf-8',
                    'format' => 'A4',
                    'orientation' => 'P',
                    'margin_left' => 6,
                    'margin_right' => 6,
                    'margin_top' => 4,
                    'margin_bottom' => 4
                ]);
                $data = $this->prepareCetakData($data, 'lampiran_intervensi_pengkajian_nyeri/cetak.html');
        $html = $this->draw('lampiran_intervensi_pengkajian_nyeri/cetak.html', ['data' => $data, 'is_mpdf' => true]);
                $mpdf->WriteHTML($html);
                $filename = 'Pengkajian_Ulang_Nyeri_' . str_replace('/', '_', $data['no_rawat']) . '.pdf';
                $mpdf->Output($filename, 'I');
                exit();
            } catch (\Throwable $e) {
                error_log('mPDF Error: ' . $e->getMessage());
            }
        }

        $data['kop_img'] = url('assets/img/KOP-SURAT.png');
        echo $this->draw('lampiran_intervensi_pengkajian_nyeri/cetak.html', ['data' => $data, 'is_mpdf' => false]);
        exit();
    }

