                    'format' => 'A4',
                    'orientation' => 'P',
                    'margin_left' => 8,
                    'margin_right' => 8,
                    'margin_top' => 5,
                    'margin_bottom' => 5
                ]);
                $data = $this->prepareCetakData($data, 'lampiran_permintaan_second_opinion/cetak.html');
        $html = $this->draw('lampiran_permintaan_second_opinion/cetak.html', ['data' => $data, 'is_mpdf' => true]);
                $mpdf->WriteHTML($html);
                $filename = 'Surat_Permintaan_Second_Opinion_' . str_replace('/', '_', $data['no_rawat']) . '.pdf';
                $mpdf->Output($filename, 'I');
                exit();
            } catch (\Throwable $e) {
                error_log('mPDF Error: ' . $e->getMessage());
            }
        }

        $data['kop_img'] = url('assets/img/KOP-SURAT.png');
        echo $this->draw('lampiran_permintaan_second_opinion/cetak.html', ['data' => $data, 'is_mpdf' => false]);
        exit();
    }

    // ==========================================
    // MANAJEMEN FORM RME (HAK AKSES PER UNIT)
    // ==========================================

    public function anyManajemenrme()
    {
        $this->core->addCSS(url('assets/css/dataTables.bootstrap.min.css'));
        $this->core->addJS(url('assets/jscripts/jquery.dataTables.min.js'));
        $this->core->addJS(url('assets/jscripts/dataTables.bootstrap.min.js'));

        $action = $_GET['action'] ?? 'manage';
        $tab    = $_GET['tab'] ?? 'status';
        $kdPoli = trim($_GET['kd_poli'] ?? ($_GET['unit_id'] ?? ''));

        // Ambil master all forms
        $all_forms = $this->db('mlite_rme_form')
            ->asc('mlite_rme_form.urutan')
            ->asc('mlite_rme_form.kategori')
            ->asc('mlite_rme_form.nama_form')
            ->toArray();

        $count_total = count($all_forms);
        $count_active = 0;
        $count_inactive = 0;
        $roles_meta = $this->getAvailableClinicalRoles();
        $role_counts = [];
        foreach (array_keys($roles_meta) as $rk) {
            $role_counts[$rk] = 0;
        }
        $kategori_list = [];

        $no = 1;
        foreach ($all_forms as &$f) {
            $f['no'] = $no++;
            $f['urutan'] = (int)($f['urutan'] ?? 0);
            if ($f['urutan'] <= 0) {
                $f['urutan'] = $f['no'];
            }
            $f['status'] = (string)($f['status'] ?? '1');
            $f['target_aktor'] = (string)($f['target_aktor'] ?? 'medis,paramedis');
            $f['roles_list'] = array_filter(array_map('trim', explode(',', $f['target_aktor'])));
            $f['catatan'] = (string)($f['catatan'] ?? '');
            $f['deskripsi'] = (string)($f['deskripsi'] ?? '');
            $f['nama_tabel'] = (string)($f['nama_tabel'] ?? '');
            $f['search_text'] = strtolower(($f['kode_form'] ?? '') . ' ' . ($f['nama_form'] ?? '') . ' ' . ($f['kategori'] ?? '') . ' ' . $f['target_aktor'] . ' ' . $f['nama_tabel'] . ' ' . $f['catatan'] . ' ' . $f['deskripsi']);

            if ($f['status'] === '1') {
                $count_active++;
            } else {
                $count_inactive++;
            }

            foreach ($f['roles_list'] as $rl) {
                if (isset($role_counts[$rl])) {
                    $role_counts[$rl]++;
                }
            }

            $assigned = [];
            $rolesWithCheck = [];
            foreach ($roles_meta as $rk => $rm) {
                $isChecked = in_array($rk, $f['roles_list'], true);
                if ($isChecked) {
                    $assigned[] = $rm;
                }
                $rolesWithCheck[] = array_merge($rm, ['checked' => $isChecked]);
            }
            $f['assigned_roles_meta'] = $assigned;
            $f['roles_with_check'] = $rolesWithCheck;

            $kat = !empty($f['kategori']) ? $f['kategori'] : 'Umum';
            if (!in_array($kat, $kategori_list, true)) {
                $kategori_list[] = $kat;
            }
        }
        unset($f);

        if (!in_array('UGD', $kategori_list, true)) {
            $kategori_list[] = 'UGD';
        }

        $preferredOrder = ['UGD', 'Rajal', 'Ranap', 'Bedah'];
        usort($kategori_list, function($a, $b) use ($preferredOrder) {
            $posA = array_search($a, $preferredOrder);
            $posB = array_search($b, $preferredOrder);
            if ($posA !== false && $posB !== false) return $posA - $posB;
            if ($posA !== false) return -1;
            if ($posB !== false) return 1;
            return strcmp($a, $b);
        });

        // Ambil semua unit langsung dari master data poliklinik SIMRS
        $units = $this->db('poliklinik')
            ->where('status', '1')
            ->where('kd_poli', '!=', '-')
            ->asc('nm_poli')
            ->toArray();

        // Pasangkan form_ids untuk tiap unit
        foreach ($units as &$u) {
            $u['id'] = $u['kd_poli'];
            $u['kode_unit'] = $u['kd_poli'];
            $u['nama_unit'] = $u['nm_poli'];
            $u['kategori'] = !empty($u['kategori_rme']) ? $u['kategori_rme'] : 'Rajal';

            $mappedForms = $this->db('mlite_rme_unit_form')
                ->join('mlite_rme_form', 'mlite_rme_form.id = mlite_rme_unit_form.form_id')
                ->where('mlite_rme_unit_form.kd_poli', $u['kd_poli'])
                ->select('mlite_rme_form.id, mlite_rme_form.kode_form, mlite_rme_form.nama_form, mlite_rme_form.status')
                ->toArray();
            $u['form_ids'] = array_column($mappedForms, 'id');
            $u['form_codes'] = array_column($mappedForms, 'kode_form');
            $u['total_form'] = count($mappedForms);
            $u['access_summary'] = !empty($u['form_codes']) ? implode(', ', $u['form_codes']) : '(Belum ada form)';
        }
        unset($u);

        $selected_unit = null;
        $assigned_form_ids = [];

        if (!empty($kdPoli)) {
            foreach ($units as $u) {
                if ($u['kd_poli'] == $kdPoli || $u['id'] == $kdPoli) {
                    $selected_unit = $u;
                    $assigned_form_ids = $u['form_ids'];
                    break;
                }
            }
        }

        return $this->draw('rme/manajemen.html', [
            'action'            => $action,
            'tab'               => $tab,
            'units'             => $units,
            'selected_unit'     => $selected_unit,
            'assigned_form_ids' => $assigned_form_ids,
            'all_forms'         => $all_forms,
            'count_total'       => $count_total,
            'count_active'      => $count_active,
            'count_inactive'    => $count_inactive,
            'available_roles'   => $roles_meta,
            'role_counts'       => $role_counts,
            'kategori_list'     => $kategori_list,
            'token'             => $_SESSION['token'] ?? ''
        ]);
    }

    public function postSimpanaksesrme()
    {
        $kdPoli = trim($_POST['kd_poli'] ?? ($_POST['unit_id'] ?? ''));
        $formIds = $_POST['form_ids'] ?? [];

        if (!empty($kdPoli)) {
            // Hapus pemetaan lama
            $this->db('mlite_rme_unit_form')->where('kd_poli', $kdPoli)->delete();

            // Masukkan pemetaan baru
            if (is_array($formIds)) {
                foreach ($formIds as $fid) {
                    $fid = (int)$fid;
                    if ($fid > 0) {
                        $this->db('mlite_rme_unit_form')->insert([
                            'kd_poli' => $kdPoli,
                            'form_id' => $fid,
                            'status'  => '1'
                        ]);
                    }
                }
            }
            $this->notify('success', 'Hak akses formulir berhasil disimpan!');
        }

        redirect(url([ADMIN, 'form_rme', 'manajemenrme']).'&action=permission&kd_poli='.$kdPoli);
    }

    public function postTogglestatusform()
    {
        $id = (int)($_POST['id'] ?? 0);
        $status = ($_POST['status'] ?? '1') === '1' ? '1' : '0';
        $catatan = trim($_POST['catatan'] ?? '');

        if ($id <= 0) {
            if (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest') {
                header('Content-Type: application/json');
                echo json_encode(['status' => 'error', 'message' => 'ID formulir tidak valid.']);
                exit();
            }
            $this->notify('danger', 'ID formulir tidak valid.');
            redirect(url([ADMIN, 'form_rme', 'manajemenrme']).'&tab=status');
        }

        $form = $this->db('mlite_rme_form')->where('id', $id)->oneArray();
        if (!$form) {
            if (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest') {
                header('Content-Type: application/json');
                echo json_encode(['status' => 'error', 'message' => 'Formulir tidak ditemukan.']);
                exit();
            }
            $this->notify('danger', 'Formulir tidak ditemukan.');
            redirect(url([ADMIN, 'form_rme', 'manajemenrme']).'&tab=status');
        }

        $dataUpdate = ['status' => $status];
        if (isset($_POST['catatan'])) {
            $dataUpdate['catatan'] = $catatan;
            $dataUpdate['deskripsi'] = $catatan;
        }

        $this->db('mlite_rme_form')->where('id', $id)->save($dataUpdate);

        $statusText = ($status === '1') ? 'diaktifkan (dipublikasikan)' : 'dinonaktifkan (disembunyikan untuk perbaikan)';
        $msg = "Formulir {$form['kode_form']} - {$form['nama_form']} berhasil {$statusText}!";

        if (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest') {
            header('Content-Type: application/json');
            echo json_encode([
                'status' => 'success',
                'message' => $msg,
                'form_status' => $status,
                'id' => $id,
                'catatan' => $catatan
            ]);
            exit();
        }

        $this->notify('success', $msg);
        redirect(url([ADMIN, 'form_rme', 'manajemenrme']).'&tab=status');
    }

    public function postUpdatetargetaktor()
    {
        $id = (int)($_POST['id'] ?? 0);
        $rawTarget = $_POST['target_aktor'] ?? '';
        if (is_array($rawTarget)) {
            $targetList = $rawTarget;
        } else {
            $targetList = explode(',', (string)$rawTarget);
        }

        $allRoles = array_keys($this->getAvailableClinicalRoles());
        $cleanRoles = [];
        foreach ($targetList as $r) {
            $r = trim(strtolower($r));
            if (in_array($r, $allRoles, true) && !in_array($r, $cleanRoles, true)) {
                $cleanRoles[] = $r;
            }
        }

        if (empty($cleanRoles)) {
            $cleanRoles = ['medis'];
        }

        $targetAktorStr = implode(',', $cleanRoles);

        if ($id <= 0) {
            header('Content-Type: application/json');
            echo json_encode(['status' => 'error', 'message' => 'ID formulir tidak valid.']);
            exit();
        }

        $form = $this->db('mlite_rme_form')->where('id', $id)->oneArray();
        if (!$form) {
            header('Content-Type: application/json');
            echo json_encode(['status' => 'error', 'message' => 'Formulir tidak ditemukan.']);
            exit();
        }

        $this->db('mlite_rme_form')->where('id', $id)->save(['target_aktor' => $targetAktorStr]);

        $rolesMeta = $this->getAvailableClinicalRoles();
        $labelList = [];
        $badgesHtml = '';
        foreach ($cleanRoles as $r) {
            $meta = $rolesMeta[$r] ?? ['name' => ucfirst($r), 'icon' => 'fa fa-user', 'color' => '#1e293b', 'bg' => '#f1f5f9', 'border' => '#cbd5e1'];
            $labelList[] = $meta['name'];
            $badgesHtml .= '<span class="badge" style="background: ' . $meta['bg'] . '; color: ' . $meta['color'] . '; border: 1px solid ' . $meta['border'] . '; font-size: 10px; font-weight: 700; padding: 2px 6px; margin-right: 3px; margin-bottom: 2px;"><i class="' . $meta['icon'] . '"></i> ' . $meta['name'] . '</span> ';
        }

        $msg = "Hak akses pengisian {$form['kode_form']} berhasil diubah ke: " . implode(', ', $labelList) . "!";

        header('Content-Type: application/json');
        echo json_encode([
            'status' => 'success',
            'ok' => true,
            'message' => $msg,
            'id' => $id,
            'target_aktor' => $targetAktorStr,
            'roles' => $cleanRoles,
            'badges_html' => $badgesHtml
        ]);
        exit();
    }

    public function postEditformrme()
    {
