    public function postSyncunitsimrs()
    {
        $syncPoli = !empty($_POST['sync_poli']);
        $syncBangsal = !empty($_POST['sync_bangsal']);
        $count = 0;

        if ($syncPoli) {
            try {
                $polis = $this->db('poliklinik')->where('status', '1')->toArray();
                foreach ($polis as $p) {
                    $kode = 'POLI_' . preg_replace('/[^A-Za-z0-9_]/', '', $p['kd_poli']);
                    $chk = $this->db('mlite_rme_unit')->where('kode_unit', $kode)->oneArray();
                    if (!$chk) {
                        $this->db('mlite_rme_unit')->insert([
                            'kode_unit'  => $kode,
                            'nama_unit'  => 'Poli ' . $p['nm_poli'],
                            'kategori'   => 'Rajal',
                            'keterangan' => 'Impor dari master poliklinik SIMRS',
                            'status'     => '1'
                        ]);
                        $count++;
                    }
                }
            } catch (\Exception $e) {}
        }

        if ($syncBangsal) {
            try {
                $bangsals = $this->db('bangsal')->where('status', '1')->toArray();
                foreach ($bangsals as $b) {
                    $kode = 'BANGSAL_' . preg_replace('/[^A-Za-z0-9_]/', '', $b['kd_bangsal']);
                    $chk = $this->db('mlite_rme_unit')->where('kode_unit', $kode)->oneArray();
                    if (!$chk) {
                        $this->db('mlite_rme_unit')->insert([
                            'kode_unit'  => $kode,
                            'nama_unit'  => 'Ruang ' . $b['nm_bangsal'],
                            'kategori'   => 'Ranap',
                            'keterangan' => 'Impor dari master bangsal SIMRS',
                            'status'     => '1'
                        ]);
                        $count++;
                    }
                }
            } catch (\Exception $e) {}
        }

        $this->notify('success', "Berhasil sinkronisasi $count unit baru dari SIMRS!");
        redirect(url([ADMIN, 'form_rme', 'manajemenrme', '?tab=unit']));
    }

    public function anyKatalogrme()
    {
        $kdPoli = trim($_GET['kd_poli'] ?? ($_GET['unit_id'] ?? ''));

        $units = $this->db('poliklinik')
            ->where('status', '1')
            ->where('kd_poli', '!=', '-')
            ->asc('kategori_rme')
            ->asc('nm_poli')
            ->toArray();

        foreach ($units as &$u) {
            $u['id'] = $u['kd_poli'];
            $u['kode_unit'] = $u['kd_poli'];
            $u['nama_unit'] = $u['nm_poli'];
            $u['kategori'] = !empty($u['kategori_rme']) ? $u['kategori_rme'] : 'Rajal';
        }
        unset($u);

        $selected_unit = null;
        if (!empty($kdPoli)) {
            foreach ($units as $u) {
                if ($u['kd_poli'] == $kdPoli || $u['id'] == $kdPoli) {
                    $selected_unit = $u;
                    break;
                }
            }
        }
        if (!$selected_unit && !empty($units)) {
            $selected_unit = $units[0];
        }

        $assigned_forms = [];
        if ($selected_unit) {
            $assigned_forms = $this->db('mlite_rme_unit_form')
                ->join('mlite_rme_form', 'mlite_rme_form.id = mlite_rme_unit_form.form_id')
                ->where('mlite_rme_unit_form.kd_poli', $selected_unit['kd_poli'])
                ->where('mlite_rme_form.status', '1')
                ->select('mlite_rme_form.*')
                ->asc('mlite_rme_form.kategori')
                ->asc('mlite_rme_form.urutan')
                ->toArray();
        }

        return $this->draw('rme/katalog.html', [
            'units'          => $units,
            'selected_unit'  => $selected_unit,
            'assigned_forms' => $assigned_forms,
            'token'          => $_SESSION['token'] ?? ''
        ]);
    }


    // ==============================================================
    // CONTROLLER METHODS ADAPTED FROM ORIGIN/FORM-RME (8 FORMS)
    // ==============================================================

    public function anyAns5manage()
    {
        if (isset($_GET['action']) && $_GET['action'] == 'delete' && !empty($_GET['id'])) {
            return $this->getAns5hapus($_GET['id']);
        }

        $this->core->addCSS(url('assets/css/dataTables.bootstrap.min.css'));
        $this->core->addJS(url('assets/jscripts/jquery.dataTables.min.js'));
        $this->core->addJS(url('assets/jscripts/dataTables.bootstrap.min.js'));

        $query = $this->db('ans5_status_anestesi')
            ->leftJoin('reg_periksa', 'reg_periksa.no_rawat = ans5_status_anestesi.no_rawat')
            ->leftJoin('pasien', 'pasien.no_rkm_medis = COALESCE(ans5_status_anestesi.no_rkm_medis, reg_periksa.no_rkm_medis)')
            ->select('ans5_status_anestesi.*, COALESCE(ans5_status_anestesi.no_rkm_medis, reg_periksa.no_rkm_medis) as no_rkm_medis, pasien.nm_pasien, pasien.jk, pasien.umur')
            ->desc('ans5_status_anestesi.id')
            ->toArray();

        $bulan = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        foreach ($query as $k => $v) {
            $query[$k]['nomor'] = $k + 1;
            if (!empty($v['tanggal']) && $v['tanggal'] != '0000-00-00') {
                $p = explode('-', $v['tanggal']);
                $query[$k]['tgl_indo'] = (int)$p[2] . ' ' . ($bulan[(int)$p[1]] ?? '') . ' ' . $p[0];
            } else {
                $query[$k]['tgl_indo'] = '-';
            }
        }

        $this->tpl->set('data', $query);
        $this->tpl->set('list', $query);
        return $this->draw('ans5/manage.html', ['data' => $query, 'list' => $query]);
    }

