    public function anyRmgd3hapus($id = null)
    {
        $id = $id ?? ($_GET['id'] ?? null);
        if ($id) {
            $this->db('mlite_triase_igd')->where('id_triase', $id)->delete();
            $this->notify('success', 'Data Lembar Triase berhasil dihapus.');
        }
        redirect(url([ADMIN, 'form_rme', 'rmgd3manage']));
    }

