            'layanan_rehabilitatif' => 'Tidak',
            'layanan_khusus' => 'Tidak',
            'layanan_intensif' => 'Tidak',
            'layanan_paliatif' => 'Tidak',
            'nama_dpjp' => '',
            'penanggung_jawab_nama' => '',
            'dokter_pengirim_nama' => ''
        ];

        if (!empty($id)) {
            $row = $this->db('surat_pengantar_ranap')->where('id', $id)->oneArray();
